    // Nesting
    // ------------------------------------------------------------------

    /// An island inside a hole inside a part: four loops, two regions, and
    /// the material on the left of every one of them.
    #[test]
    fn test_nesting_depth_three_gives_two_regions_oriented_the_house_way() {
        let frame = extrude(
            &rect(0.0, 0.0, 100.0, 100.0),
            &[reversed(&rect(20.0, 20.0, 80.0, 80.0))],
            0.0,
            5.0,
        );
        let island = extrude(
            &rect(35.0, 35.0, 65.0, 65.0),
            &[reversed(&rect(45.0, 45.0, 55.0, 55.0))],
            0.0,
            5.0,
        );
        let mut positions = frame.positions.clone();
        let mut indices = frame.indices.clone();
        let base = positions.len() as u32;
        positions.extend(island.positions.iter().copied());
        indices.extend(island.indices.iter().map(|i| i + base));

        let out = section_at_z(&positions, &indices, 2.5, &SectionOptions::default()).unwrap();
        assert_eq!(out.regions.len(), 2, "{}", out.regions.len());

        // Largest first.
        let (frame_r, island_r) = (&out.regions[0], &out.regions[1]);
        assert!((frame_r.outer.area() - 10_000.0).abs() < 1e-9);
        assert_eq!(frame_r.holes.len(), 1);
        assert!((frame_r.holes[0].area() - 3_600.0).abs() < 1e-9);
        assert!((island_r.outer.area() - 900.0).abs() < 1e-9);
        assert_eq!(island_r.holes.len(), 1);
        assert!((island_r.holes[0].area() - 100.0).abs() < 1e-9);

        // The island is *not* a hole of the frame: it is material.
        assert!((out.area() - 7_200.0).abs() < 1e-9, "area {}", out.area());
        for r in &out.regions {
            assert!(r.outer.is_ccw(), "an outer boundary runs clockwise");
            for h in &r.holes {
                assert!(!h.is_ccw(), "a hole runs counter-clockwise");
            }
        }
        // Material on the left, checked directly: step left off any loop and
        // you are in metal.
        for l in out.loops() {
            let a = l.points[0];
            let b = l.points[1];
            let (dx, dy) = (b.x - a.x, b.y - a.y);
            let len = dx.hypot(dy);
            let mid = Point2D::new(
                0.5 * (a.x + b.x) - dy / len * 0.01,
                0.5 * (a.y + b.y) + dx / len * 0.01,
            );
            assert!(out.contains(mid), "left of {a:?}->{b:?} is not material");
        }
    }

