    #[test]
    fn test_is_prismatic_separates_an_extrusion_from_a_cone_and_a_sphere() {
        let p = plate_with_bore();
        let flat = is_prismatic(&p.positions, &p.indices, 0.0, 10.0, 0.01).unwrap();
        assert!(flat.prismatic);
        assert!(
            flat.max_boundary_distance < 1e-9,
            "extrusion disagrees by {}",
            flat.max_boundary_distance
        );
        assert!(flat.symmetric_difference_area < 1e-9);

        // A Ø20 cone 20 tall: the sampled radius runs 9.5 at z = 1 down to
        // 0.5 at z = 19, against 5.0 at the reference height.
        let (cp, ci) = cone(10.0, 20.0, 256);
        let taper = is_prismatic(&cp, &ci, 0.0, 20.0, 0.01).unwrap();
        assert!(!taper.prismatic);
        assert!(
            (taper.max_boundary_distance - 4.5).abs() < 0.01,
            "cone worst {} at z {}",
            taper.max_boundary_distance,
            taper.worst_z
        );
        assert!(
            (taper.worst_z - 1.0).abs() < 1e-9 || (taper.worst_z - 19.0).abs() < 1e-9,
            "worst at z {}",
            taper.worst_z
        );

        let (sp, si) = uv_sphere(10.0, 128, 64);
        let ball = is_prismatic(&sp, &si, -10.0, 10.0, 0.01).unwrap();
        assert!(!ball.prismatic);
        // r(z) = sqrt(100 - z²): √19 = 4.359 at z = ±9 against 10 at the
        // equator, so the two sections stand 5.641 mm apart.
        assert!(
            (ball.max_boundary_distance - 5.641).abs() < 0.02,
            "sphere worst {}",
            ball.max_boundary_distance
        );
    }

