    // ------------------------------------------------------------------
    // Cleanup
    // ------------------------------------------------------------------

    /// Sample a loop densely: the deepest intrusion of a chord is in its
    /// middle, not at its ends.
    fn boundary_samples(o: &Outline) -> Vec<Point2D> {
        let mut pts = Vec::new();
        for l in o.loops() {
            let n = l.points.len();
            for i in 0..n {
                let (a, b) = (l.points[i], l.points[(i + 1) % n]);
                for k in 0..20 {
                    let t = k as f64 / 20.0;
                    pts.push(Point2D::new(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t));
                }
            }
        }
        pts
    }

    /// The worst distance any point of `simplified`'s boundary sits *inside*
    /// `original`'s material: how far the contour would gouge.
    fn worst_intrusion(original: &Outline, simplified: &Outline) -> f64 {
        boundary_samples(simplified)
            .into_iter()
            .map(|p| original.signed_distance(p))
            .fold(f64::MIN, f64::max)
    }

    #[test]
    fn test_simplification_keeps_its_promise_about_the_material_side() {
        let outline = stator_outline();
        let before: usize = outline.loops().map(|l| l.points.len()).sum();

        // Symmetric: deviation either way, capped at the tolerance.
        let both = outline.simplify(&SimplifyOptions::new(0.05));
        let after: usize = both.loops().map(|l| l.points.len()).sum();
        assert!(after < before / 2, "{before} -> {after} points");
        let into = worst_intrusion(&outline, &both);
        assert!(into <= 0.05 + 1e-9, "symmetric simplify gouges {into} mm");
        assert!(into > 0.0, "nothing moved inward, so the bound is vacuous");

        // Outward only: the contour may leave stock, never take it.
        let out = outline.simplify(&SimplifyOptions::outward_only(0.05));
        let out_pts: usize = out.loops().map(|l| l.points.len()).sum();
        assert!(out_pts < before, "{before} -> {out_pts} points");
        let into = worst_intrusion(&outline, &out);
        assert!(into <= 1e-9, "outward-only simplify gouges {into} mm");
    }

    #[test]
    fn test_a_circular_hole_comes_back_as_arcs() {
        let p = plate_with_bore();
        let out = section_at_z(&p.positions, &p.indices, 5.0, &SectionOptions::default()).unwrap();
        let hole = &out.regions[0].holes[0];
        let contour = hole.to_contour_with_arcs(0.02);
        let arcs = contour
            .segments
            .iter()
            .filter(|s| matches!(s, ContourSegment::Arc { .. }))
            .count();
        assert!((2..=3).contains(&arcs), "{arcs} arc(s)");
        assert!(contour.is_closed(1e-9));
        // Flattening the arcs back has to land on the same circle.
        let back = Loop::from_contour(&contour, 1e-4);
        let fit = back.fit_circle().unwrap();
        assert!((fit.radius - 5.0).abs() < 0.02, "radius {}", fit.radius);
        assert!(fit.center.distance_to(&Point2D::new(15.0, 10.0)) < 1e-6);

        // A straight-sided part gets no arcs at all.
        let square = Loop::new(rect(0.0, 0.0, 10.0, 10.0));
        let c = square.to_contour_with_arcs(0.02);
        assert!(c
            .segments
            .iter()
            .all(|s| matches!(s, ContourSegment::Line { .. })));
    }

