    #[test]
    fn test_dxf_round_trip_is_exact() {
        let p = plate_with_bore();
        let out = section_at_z(&p.positions, &p.indices, 5.0, &SectionOptions::default()).unwrap();
        let text = write_dxf(&out);
        let back = read_dxf(&text).unwrap();
        let diff = compare_outlines(&out, &back, &CompareOptions::default());
        // The DXF carries six decimals, so a coordinate can move 0.5 nm and
        // the Ø10 bore's 31 mm of boundary can move ~1.6e-5 mm² of area.
        assert!(
            diff.symmetric_difference_area < 1e-4,
            "{} mm² apart",
            diff.symmetric_difference_area
        );
        assert!(diff.max_boundary_distance < 1e-6);
        assert_eq!(diff.hole_count_a, 1);
        assert_eq!(diff.hole_count_b, 1);
        assert!(diff.unmatched_a.is_empty() && diff.unmatched_b.is_empty());
        assert!(diff.holes[0].diameter_error() < 1e-6);
    }

    #[test]
    fn test_dxf_reader_refuses_what_it_cannot_represent() {
        let good = "0\nSECTION\n2\nENTITIES\n0\nLWPOLYLINE\n90\n3\n70\n1\n10\n0\n20\n0\n\
                    10\n10\n20\n0\n10\n0\n20\n10\n0\nENDSEC\n0\nEOF\n";
        assert!(read_dxf(good).is_ok());

        let bulged = good.replace("10\n10\n20\n0\n", "10\n10\n20\n0\n42\n0.5\n");
        let err = read_dxf(&bulged).unwrap_err();
        assert!(err.to_string().contains("bulge"), "{err}");

        let open = good.replace("70\n1\n", "70\n0\n");
        let err = read_dxf(&open).unwrap_err();
        assert!(err.to_string().contains("not closed"), "{err}");

        let line = good.replace("0\nENDSEC", "0\nLINE\n10\n0\n20\n0\n0\nENDSEC");
        let err = read_dxf(&line).unwrap_err();
        assert!(err.to_string().contains("entity LINE"), "{err}");
    }

