    /// The real job: the plate whose DXF was lost. Extrude the fixture to
    /// the 6 mm plate it describes, break it into soup the way the failing
    /// union does, section it back, and check the DXF against the solid —
    /// which is the check that was missing (friction log item 16).
    #[test]
    fn test_stator_section_matches_its_dxf() {
        let dxf = stator_outline();
        assert_eq!(dxf.regions.len(), 1);
        assert_eq!(dxf.regions[0].holes.len(), 4);

        let holes: Vec<Vec<Point2D>> = dxf.regions[0]
            .holes
            .iter()
            .map(|h| h.points.clone())
            .collect();
        let p = extrude(&dxf.regions[0].outer.points, &holes, 0.0, 6.0);
        let (positions, indices) = explode_to_soup(&p.positions, &p.indices, 0x57A7_0121);

        let solid = section_at_z(&positions, &indices, 3.0, &SectionOptions::default()).unwrap();
        assert_eq!(solid.regions.len(), 1, "{}", solid.regions.len());
        assert_eq!(solid.regions[0].holes.len(), 4);

        let diff = compare_outlines(&dxf, &solid, &CompareOptions::default());
        assert!(
            diff.symmetric_difference_area < 0.05,
            "DXF and solid differ by {} mm²",
            diff.symmetric_difference_area
        );
        assert_eq!(diff.hole_count_a, 4);
        assert_eq!(diff.hole_count_b, 4);
        assert!(diff.unmatched_a.is_empty() && diff.unmatched_b.is_empty());
        for h in &diff.holes {
            assert!(h.center_offset < 1e-3, "{h:?}");
            assert!(h.diameter_error() < 1e-3, "{h:?}");
        }

        // Three M3 pilots: Ø2.5, where the fixture puts them.
        let circles = solid.circular_holes(1e-4);
        assert_eq!(circles.len(), 3, "{circles:#?}");
        let mut centres: Vec<Point2D> = circles.iter().map(|c| c.fit.center).collect();
        centres.sort_by(|a, b| a.x.partial_cmp(&b.x).unwrap());
        let expected = [
            Point2D::new(-31.2960, 8.3857),
            Point2D::new(8.3857, -31.2960),
            Point2D::new(22.9103, 22.9103),
        ];
        for (got, want) in centres.iter().zip(expected.iter()) {
            assert!(got.distance_to(want) < 1e-3, "{got:?} vs {want:?}");
        }
        for c in &circles {
            assert!(
                (c.fit.diameter() - 2.5).abs() < 1e-3,
                "Ø{}",
                c.fit.diameter()
            );
        }
        // 1309.24 mm² of metal, 6 mm thick, is the 7853 mm³ the kernel
        // solves the stator to.
        assert!(
            (solid.area() * 6.0 - 7855.4).abs() < 1.0,
            "{} mm³",
            solid.area() * 6.0
        );
    }

    /// A hundred thousand triangles of soup is the size the stator actually
    /// arrives at. A wall-clock guard, not a benchmark.
    #[test]
    fn test_a_hundred_thousand_triangle_soup_sections_in_seconds() {
        let dxf = stator_outline();
        let holes: Vec<Vec<Point2D>> = dxf.regions[0]
            .holes
            .iter()
            .map(|h| h.points.clone())
            .collect();
        let p = extrude(&dxf.regions[0].outer.points, &holes, 0.0, 6.0);
        let (positions, indices) = grow_to(p.positions, p.indices, 100_000);
        let (positions, indices) = explode_to_soup(&positions, &indices, 7);
        let triangles = indices.len() / 3;
        assert!(triangles >= 100_000, "{triangles} triangles");

        let start = std::time::Instant::now();
        let solid = section_at_z(&positions, &indices, 3.0, &SectionOptions::default()).unwrap();
        let elapsed = start.elapsed();

        assert_eq!(solid.regions.len(), 1);
        assert_eq!(solid.regions[0].holes.len(), 4);
        let diff = compare_outlines(&dxf, &solid, &CompareOptions::default());
        assert!(
            diff.symmetric_difference_area < 0.05,
            "{} mm²",
            diff.symmetric_difference_area
        );
        assert!(
            elapsed.as_secs_f64() < 30.0,
            "{triangles} triangles took {elapsed:?}"
        );
        println!("{triangles} triangles sectioned in {elapsed:?}");
    }

