    /// A stale DXF is one whose holes have moved or grown. Say which.
    #[test]
    fn test_compare_outlines_reports_hole_mismatches() {
        let good = Outline::from_loops(vec![
            Loop::new(rect(0.0, 0.0, 40.0, 40.0)),
            Loop::new(reversed(&regular_polygon(10.0, 10.0, 2.0, 64))),
            Loop::new(reversed(&regular_polygon(30.0, 30.0, 2.0, 64))),
        ]);
        let stale = Outline::from_loops(vec![
            Loop::new(rect(0.0, 0.0, 40.0, 40.0)),
            Loop::new(reversed(&regular_polygon(10.2, 10.0, 2.5, 64))),
        ]);
        let d = compare_outlines(&good, &stale, &CompareOptions::default());
        assert_eq!(d.hole_count_a, 2);
        assert_eq!(d.hole_count_b, 1);
        assert_eq!(d.unmatched_a.len(), 1, "the dropped hole is not reported");
        assert!(d.unmatched_b.is_empty());
        assert_eq!(d.holes.len(), 1);
        assert!(
            (d.holes[0].center_offset - 0.2).abs() < 1e-6,
            "{:?}",
            d.holes[0]
        );
        assert!(
            (d.holes[0].diameter_error() - 1.0).abs() < 1e-3,
            "{:?}",
            d.holes[0]
        );
        assert!(!d.agrees_within(0.01));
    }

